1	import { db } from "@/lib/db";
2	import { requireUser } from "@/lib/auth";
3	import { track, EVENTS } from "@/lib/events";
4	
5	export const dynamic = "force-dynamic";
6	
7	// Same ceiling the create route applies (app/api/projects/route.ts). Kept in
8	// sync by hand rather than imported: route modules aren't a shared-constants
9	// home, and that file doesn't export it.
10	const NAME_MAX = 80;
11	
12	// Mirrors slugify() in app/api/projects/route.ts. Duplicated rather than
13	// imported for the same reason as NAME_MAX — importing across route modules
14	// couples two request entrypoints for one pure function. The random suffix is
15	// what makes collisions rare; POST below still retries on the off chance.
16	function slugify(name: string): string {
17	  const base = name
18	    .toLowerCase()
19	    .replace(/[^a-z0-9]+/g, "-")
20	    .replace(/^-+|-+$/g, "")
21	    .slice(0, 40);
22	  return (base || "site") + "-" + Math.random().toString(36).slice(2, 7);
23	}
24	
25	/** Prisma's unique-constraint violation. Structural check so this file needn't import the Prisma error namespace. */
26	function isUniqueViolation(err: unknown): boolean {
27	  return typeof err === "object" && err !== null && (err as { code?: string }).code === "P2002";
28	}
29	
30	export async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {
31	  const user = await requireUser().catch(() => null);
32	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
33	  const { id } = await params;
34	
35	  const project = await db.project.findFirst({
36	    where: { id, userId: user.id },
37	    include: {
38	      // Source is what the agent/Code-view work with; the compiled build
39	      // output isn't meant to be shown or edited directly.
40	      files: { where: { published: false, kind: "source" } },
41	      messages: { orderBy: { createdAt: "asc" } },
42	    },
43	  });
44	  if (!project) return Response.json({ error: "Project not found." }, { status: 404 });
45	
46	  return Response.json({ project });
47	}
48	
49	/**
50	 * Rename. Name only.
51	 *
52	 * THE SLUG IS DELIBERATELY NOT REGENERATED HERE.
53	 *
54	 * `slug` is the published address (`<slug>.kodely.site`, and the row the public
55	 * site route resolves by). Renaming is a labelling act — the user is fixing what
56	 * their dashboard calls the thing — and it must not be able to move a live site
57	 * out from under its own URL. If rename re-slugged:
58	 *   - every existing inbound link, share, QR code, and search-engine result for
59	 *     the published site would 404, silently, with no redirect to fall back on;
60	 *   - the old slug is globally unique and would be released back into the pool,
61	 *     so someone else could later claim the exact URL the user just vacated —
62	 *     a URL takeover triggered by an action that looks purely cosmetic.
63	 *
64	 * The same rule applies to unpublished projects, on purpose. Making it
65	 * conditional ("re-slug only while it's still a draft") would mean the slug
66	 * shown in the dashboard silently changes for a draft but freezes at publish —
67	 * a rule nobody can predict from the UI, and one that changes a preview URL the
68	 * user may already have handed to someone. One rule, always true: a slug is
69	 * assigned once at creation and never moves.
70	 *
71	 * A user who genuinely wants a different address wants a different site, and
72	 * that is what POST (duplicate) gives them — a new slug, no lost links.
73	 */
74	export async function PATCH(req: Request, { params }: { params: Promise<{ id: string }> }) {
75	  const user = await requireUser().catch(() => null);
76	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
77	  const { id } = await params;
78	
79	  const body = (await req.json().catch(() => null)) as { name?: unknown } | null;
80	  if (typeof body?.name !== "string") {
81	    return Response.json({ error: "A name is required." }, { status: 400 });
82	  }
83	  // Trim, cap, then trim again — slicing at 80 can leave a trailing space.
84	  const name = body.name.trim().slice(0, NAME_MAX).trim();
85	  if (!name) {
86	    // The create route falls back to "Untitled site" for a missing name, but a
87	    // rename is an explicit act: silently renaming someone's site to a
88	    // placeholder because their input was blank is worse than refusing.
89	    return Response.json({ error: "A name is required." }, { status: 400 });
90	  }
91	
92	  // updateMany, not update: `update` can only filter on unique fields, so it
93	  // would have to take the id alone and check ownership in a second query.
94	  // Scoping by { id, userId } in ONE query is what makes a wrong-user id
95	  // indistinguishable from a nonexistent one.
96	  const { count } = await db.project.updateMany({
97	    where: { id, userId: user.id },
98	    data: { name },
99	  });
100	  if (count === 0) return Response.json({ error: "Project not found." }, { status: 404 });
101	
102	  return Response.json({ project: { id, name } });
103	}
104	
105	/**
106	 * Duplicate — "make a variant of this" without paying for a whole new
107	 * generation. Charges no credits because nothing is generated: this is a row
108	 * copy, no model call anywhere on the path.
109	 *
110	 * What is copied: the name (suffixed), and every DRAFT file.
111	 * What is NOT copied:
112	 *   - publish state. `publishedAt` stays null and no `published: true` rows are
113	 *     copied, so a duplicate cannot silently go live at a new URL. Going live is
114	 *     always an explicit act through the publish route.
115	 *   - messages and builds. The copy is a fresh starting point, not a forked
116	 *     history; carrying over another project's conversation and its build/cost
117	 *     records would misattribute both.
118	 *
119	 * Draft files are copied for BOTH kinds, not just `kind: "source"`. The editor's
120	 * preview reads draft `kind: "build"` rows (app/api/preview/[id]) — copying only
121	 * source would hand the user a duplicate that renders "Nothing built yet" and
122	 * force a paid rebuild to see it, which is precisely the cost this feature
123	 * exists to avoid. Both draft trees together are the complete working state.
124	 */
125	export async function POST(_req: Request, { params }: { params: Promise<{ id: string }> }) {
126	  const user = await requireUser().catch(() => null);
127	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
128	  const { id } = await params;
129	
130	  const source = await db.project.findFirst({
131	    where: { id, userId: user.id },
132	    include: { files: { where: { published: false } } },
133	  });
134	  if (!source) return Response.json({ error: "Project not found." }, { status: 404 });
135	
136	  // Budget for the suffix before truncating, so the copy marker always survives
137	  // rather than being the part that gets sliced off an already-long name.
138	  const SUFFIX = " (copy)";
139	  const name = source.name.slice(0, NAME_MAX - SUFFIX.length).trim() + SUFFIX;
140	
141	  // The project row and its files are created in one transaction: a project
142	  // that exists with an empty file tree is a broken duplicate, and worse than
143	  // no duplicate at all.
144	  //
145	  // Retry wraps the WHOLE transaction. slugify()'s random suffix makes a
146	  // collision unlikely but not impossible, and a failed statement aborts the
147	  // surrounding Postgres transaction — so retrying the create in place would
148	  // run inside a poisoned transaction.
149	  let copy: { id: string; name: string; slug: string } | null = null;
150	  for (let attempt = 0; attempt < 5; attempt++) {
151	    try {
152	      copy = await db.$transaction(async (tx) => {
153	        const created = await tx.project.create({
154	          data: { userId: user.id, name, slug: slugify(name) },
155	        });
156	        if (source.files.length > 0) {
157	          await tx.projectFile.createMany({
158	            data: source.files.map((f) => ({
159	              projectId: created.id,
160	              path: f.path,
161	              content: f.content,
162	              published: false,
163	              kind: f.kind,
164	            })),
165	          });
166	        }
167	        return created;
168	      });
169	      break;
170	    } catch (err) {
171	      if (isUniqueViolation(err) && attempt < 4) continue;
172	      throw err;
173	    }
174	  }
175	  if (!copy) return Response.json({ error: "Couldn't duplicate this site." }, { status: 500 });
176	
177	  // A duplicate really is a project created, so it belongs in the same funnel.
178	  // EVENTS is a closed vocabulary by design (see lib/events.ts), so the copy is
179	  // distinguished by a prop rather than by inventing a name.
180	  track(EVENTS.projectCreated, {
181	    userId: user.id,
182	    props: { projectId: copy.id, source: "duplicate", sourceProjectId: source.id },
183	  });
184	
185	  return Response.json({ project: copy });
186	}
187	
188	/**
189	 * Delete. Irreversible — there is no soft-delete column and no undo.
190	 *
191	 * Cascade behaviour below was verified against the live Postgres FK catalog
192	 * (pg_constraint.confdeltype), not just read off schema.prisma:
193	 *   ProjectFile -> Project  ON DELETE CASCADE
194	 *   Message     -> Project  ON DELETE CASCADE
195	 *   Build       -> Project  ON DELETE CASCADE
196	 *   CreditLedger -> Build   ON DELETE SET NULL
197	 *
198	 * Two consequences worth stating explicitly:
199	 *
200	 * 1. THIS TAKES A PUBLISHED SITE OFFLINE. The cascade removes the
201	 *    `published: true` rows the public site route serves, and the Project row
202	 *    it resolves the slug by — so `<slug>.kodely.site` 404s. Deleting is the
203	 *    only way to withdraw a published site, and it must actually withdraw it.
204	 *    (Note: that route sends `Cache-Control: public, max-age=60`, so an already
205	 *    cached response can survive up to a minute at the edge/browser.)
206	 *
207	 * 2. THE CREDIT LEDGER SURVIVES. Builds cascade away, but CreditLedger rows
208	 *    referencing them are SET NULL, not deleted — the rows remain with
209	 *    `buildId: null`. getBalance() reads `balanceAfter` off the newest ledger
210	 *    row (lib/credits.ts), so a delete cannot alter, refund, or erase spend.
211	 *    That is the correct behaviour for an auditable ledger: deleting the
212	 *    artifact does not un-charge the work that produced it.
213	 */
214	export async function DELETE(_req: Request, { params }: { params: Promise<{ id: string }> }) {
215	  const user = await requireUser().catch(() => null);
216	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
217	  const { id } = await params;
218	
219	  // Read before deleting so the event can record whether a LIVE site just went
220	  // offline — afterwards there is nothing left to ask. Ownership is still scoped
221	  // in the delete itself, so this read is for telemetry, not authorization.
222	  const existing = await db.project.findFirst({
223	    where: { id, userId: user.id },
224	    select: { publishedAt: true, createdAt: true },
225	  });
226	
227	  // Ownership scoped in the same query as the id — see the note on PATCH.
228	  const { count } = await db.project.deleteMany({ where: { id, userId: user.id } });
229	  if (count === 0) return Response.json({ error: "Project not found." }, { status: 404 });
230	
231	  track(EVENTS.projectDeleted, {
232	    userId: user.id,
233	    props: {
234	      projectId: id,
235	      wasPublished: Boolean(existing?.publishedAt),
236	      ageHours: existing
237	        ? Math.round((Date.now() - existing.createdAt.getTime()) / 3_600_000)
238	        : null,
239	    },
240	  });
241	
242	  return Response.json({ ok: true });
243	}
