3	// The starter every new project begins from — a real Vite + React + TS +
4	// Tailwind app, not a blank page. The agent edits these files; it never
5	// chooses or installs dependencies itself (see lib/build-site.ts) — package.json
6	// here is the ONLY dependency set that will ever exist, which is what keeps
7	// the server-side build safe to run without per-generation `npm install`.
8	export const FOUNDATION_FILES: FileMap = {
9	  "package.json": JSON.stringify(
10	    {
11	      name: "kodely-site",
12	      private: true,
13	      version: "0.0.0",
14	      type: "module",
15	      scripts: { build: "vite build" },
16	      dependencies: {
17	        react: "^19.2.8",
18	        "react-dom": "^19.2.8",
19	      },
20	      devDependencies: {
21	        "@tailwindcss/vite": "^4.3.3",
22	        "@vitejs/plugin-react": "^6.0.5",
23	        tailwindcss: "^4.3.3",
24	        typescript: "^7.0.2",
25	        vite: "^8.2.1",
26	      },
27	    },
28	    null,
29	    2,
30	  ),
31	
32	  "vite.config.ts": `import { defineConfig } from "vite";
33	import react from "@vitejs/plugin-react";
34	import tailwindcss from "@tailwindcss/vite";
35	
36	export default defineConfig({
37	  plugins: [react(), tailwindcss()],
38	  build: { outDir: "dist" },
39	});
40	`,
41	
42	  "tsconfig.json": JSON.stringify(
43	    {
44	      compilerOptions: {
45	        target: "ES2022",
46	        useDefineForClassFields: true,
47	        lib: ["ES2022", "DOM", "DOM.Iterable"],
48	        module: "ESNext",
49	        skipLibCheck: true,
50	        moduleResolution: "bundler",
51	        allowImportingTsExtensions: true,
52	        resolveJsonModule: true,
53	        isolatedModules: true,
54	        noEmit: true,
55	        jsx: "react-jsx",
56	        strict: true,
57	      },
58	      include: ["src"],
59	    },
60	    null,
61	    2,
62	  ),
63	
64	  // The builder is instructed to rewrite the title/description/OG tags below
65	  // for every new site (see lib/agent.ts). If it doesn't, lib/site-seo.ts
66	  // substitutes the project name at serve time — a published site must never
67	  // show "Kodely Site" in a browser tab, a search result, or a link preview.
68	  "index.html": `<!doctype html>
69	<html lang="en">
70	  <head>
71	    <meta charset="UTF-8" />
72	    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
73	    <title>Kodely Site</title>
74	    <meta name="description" content="" />
75	    <meta property="og:title" content="" />
76	    <meta property="og:description" content="" />
77	    <meta property="og:type" content="website" />
78	    <meta name="twitter:card" content="summary_large_image" />
79	  </head>
80	  <body>
81	    <div id="root"></div>
82	    <script type="module" src="/src/main.tsx"></script>
83	  </body>
84	</html>
85	`,
86	
87	  "src/main.tsx": `import { StrictMode } from "react";
88	import { createRoot } from "react-dom/client";
89	import App from "./App";
90	import "./index.css";
91	
92	createRoot(document.getElementById("root")!).render(
93	  <StrictMode>
94	    <App />
95	  </StrictMode>,
96	);
97	`,
98	
99	  "src/index.css": `@import "tailwindcss";
100	
101	:root {
102	  color-scheme: light dark;
103	}
104	`,
105	
106	  "src/App.tsx": `import { Section } from "./components/ui/Section";
107	import { Button } from "./components/ui/Button";
108	
109	export default function App() {
110	  return (
111	    <Section>
112	      <h1 className="text-4xl font-bold tracking-tight text-neutral-900">Welcome</h1>
113	      <p className="mt-4 text-lg text-neutral-600">
114	        Describe what you want built, and I'll take it from here.
115	      </p>
116	      <Button className="mt-6">Get started</Button>
117	    </Section>
118	  );
119	}
120	`,
121	
122	  "src/components/ui/Button.tsx": `import { forwardRef, type ButtonHTMLAttributes } from "react";
123	
124	type Variant = "primary" | "secondary" | "ghost";
125	
126	const variants: Record<Variant, string> = {
127	  primary: "bg-neutral-900 text-white hover:bg-neutral-800",
128	  secondary: "bg-neutral-100 text-neutral-900 hover:bg-neutral-200",
129	  ghost: "text-neutral-900 hover:bg-neutral-100",
130	};
131	
132	type Props = ButtonHTMLAttributes<HTMLButtonElement> & { variant?: Variant };
133	
134	export const Button = forwardRef<HTMLButtonElement, Props>(function Button(
135	  { variant = "primary", className = "", ...props },
136	  ref,
137	) {
138	  return (
139	    <button
140	      ref={ref}
141	      className={\`inline-flex items-center justify-center rounded-lg px-4 py-2.5 text-sm font-medium transition-colors \${variants[variant]} \${className}\`}
142	      {...props}
143	    />
144	  );
145	});
146	`,
147	
148	  "src/components/ui/Card.tsx": `import type { HTMLAttributes } from "react";
149	
150	export function Card({ className = "", ...props }: HTMLAttributes<HTMLDivElement>) {
151	  return (
152	    <div
153	      className={\`rounded-2xl border border-neutral-200 bg-white p-6 shadow-sm \${className}\`}
154	      {...props}
155	    />
156	  );
157	}
158	`,
159	
160	  "src/components/ui/Section.tsx": `import type { HTMLAttributes } from "react";
161	
162	export function Section({ className = "", ...props }: HTMLAttributes<HTMLElement>) {
163	  return <section className={\`mx-auto max-w-5xl px-6 py-16 \${className}\`} {...props} />;
164	}
165	`,
166	
167	  "src/components/ui/Nav.tsx": `import type { HTMLAttributes } from "react";
168	
169	export function Nav({ className = "", ...props }: HTMLAttributes<HTMLElement>) {
170	  return (
171	    <nav
172	      className={\`sticky top-0 z-10 border-b border-neutral-200 bg-white/80 backdrop-blur \${className}\`}
173	      {...props}
174	    />
175	  );
176	}
177	`,
178	};
