250	/**
251	 * Runs the plan → generate → apply loop, streaming progress as it goes.
252	 * Token usage is accumulated across every turn so the caller can meter the
253	 * true cost of the build (including the repair turns, which we may not bill).
254	 */
255	// Which generation engine to use.
256	//   api (default) — metered Anthropic API via ANTHROPIC_API_KEY. Real cost,
257	//                   real usage telemetry, real credit charges.
258	//   sdk           — Claude Agent SDK on this machine's `claude setup-token`
259	//                   subscription login. No metered spend, so no cost data and
260	//                   0 credits charged. See lib/agent-sdk.ts for the caveats.
261	// Defaults to `api` so a fresh clone never silently runs on someone's personal
262	// subscription; the environment opts in.
263	export const ENGINE = process.env.KODELY_ENGINE === "sdk" ? "sdk" : "api";
264	
265	export async function* runAgent(opts: RunOptions): AsyncGenerator<AgentEvent> {
266	  // One place decides, and the env var wins. `KODELY_ENGINE=sdk` pins every
267	  // run to the SDK; when it is at its `api` default the caller may opt an
268	  // individual run in. Written as `||` rather than reading opts first so the
269	  // pin cannot be overridden by a caller — see the note on RunOptions.engine.
270	  const engine = ENGINE === "sdk" || opts.engine === "sdk" ? "sdk" : "api";
271	
272	  if (engine === "sdk") {
273	    // Deliberately no try/catch fallback to the API engine: if the SDK is not
274	    // authenticated this must fail loudly rather than quietly spend money on
275	    // the metered key the operator asked not to use.
276	    const { runAgentSdk } = await import("./agent-sdk");
277	    yield* runAgentSdk(opts, SYSTEM);
278	    return;
279	  }
280	
281	  const model = MODELS.builder;
282	  // Effort is the sharpest cost lever we have: a first build is a blank-page
283	  // design problem and earns `high`, while a targeted tweak lands the same
284	  // result at `medium` for a fraction of the thinking tokens.
285	  const effort = opts.kind === "create" ? EFFORT.create : EFFORT.edit;
286	
287	  const messages: Anthropic.MessageParam[] = [];
288	  for (const turn of opts.history) {
289	    messages.push({ role: turn.role, content: turn.content });
290	  }
291	  const requestText = `${describeFiles(opts.files)}\n\n--- Request ---\n${opts.request}`;
292	  if (opts.image) {
293	    messages.push({
294	      role: "user",
295	      content: [
296	        {
297	          type: "image",
298	          source: {
299	            type: "base64",
300	            media_type: opts.image.mediaType as "image/png" | "image/jpeg" | "image/webp",
301	            data: opts.image.data,
302	          },
303	        },
304	        { type: "text", text: `${requestText}\n\n(A reference image is attached above — use it as visual/style guidance for the site.)` },
305	      ],
306	    });
307	  } else {
308	    messages.push({ role: "user", content: requestText });
309	  }
310	
311	  const totals = {
312	    inputTokens: 0,
313	    outputTokens: 0,
314	    cacheReadTokens: 0,
315	    cacheWriteTokens: 0,
316	  };
317	
318	  // Bounded so a confused model can never bill the user for an endless loop.
319	  const MAX_TURNS = 8;
320	
321	  for (let turn = 0; turn < MAX_TURNS; turn++) {
322	    if (opts.signal?.aborted) return;
323	
324	    const stream = anthropic.messages.stream(
325	      {
326	        model,
327	        max_tokens: 32_000,
328	        thinking: { type: "adaptive" },
329	        output_config: { effort },
330	        system: [{ type: "text", text: SYSTEM, cache_control: { type: "ephemeral" } }],
331	        tools: TOOLS,
332	        messages,
333	      },
334	      { signal: opts.signal },
335	    );
336	
337	    for await (const event of stream) {
338	      if (event.type === "content_block_delta" && event.delta.type === "text_delta") {
339	        yield { type: "text", text: event.delta.text };
340	      }
341	    }
342	
343	    const message = await stream.finalMessage();
344	    totals.inputTokens += message.usage.input_tokens ?? 0;
345	    totals.outputTokens += message.usage.output_tokens ?? 0;
346	    totals.cacheReadTokens += message.usage.cache_read_input_tokens ?? 0;
347	    totals.cacheWriteTokens += message.usage.cache_creation_input_tokens ?? 0;
348	
349	    if (message.stop_reason === "refusal") {
350	      throw new Error(
351	        "The request was declined. Try describing the site you want in different terms.",
352	      );
353	    }
354	
355	    const toolUses = message.content.filter(
356	      (b): b is Anthropic.ToolUseBlock => b.type === "tool_use",
357	    );
358	
359	    if (toolUses.length === 0) {
360	      yield { type: "usage", model, ...totals };
361	      return;
362	    }
363	
364	    messages.push({ role: "assistant", content: message.content });
365	
366	    const results: Anthropic.ToolResultBlockParam[] = [];
367	    for (const use of toolUses) {
368	      const input = use.input as {
369	        path?: string;
370	        content?: string;
371	        query?: string;
372	        kind?: string;
373	        limit?: number;
374	      };
375	
376	      // Handled before the path check below — this is the one tool that takes
