389	        continue;
390	      }
391	
392	      const path = normalizePath(input.path ?? "");
393	
394	      if (!path) {
395	        results.push({
396	          type: "tool_result",
397	          tool_use_id: use.id,
398	          content: `Rejected: '${input.path}' is not a valid project-relative path.`,
399	          is_error: true,
400	        });
401	        continue;
402	      }
403	
404	      // Narrate before applying, so the line appears while the write is
405	      // happening rather than after it lands.
406	      const line = narrateTool(use.name, { path });
407	      if (line) yield { type: "progress", text: line };
408	
409	      if (use.name === "write_file") {
410	        const ok = await opts.onWrite(path, input.content ?? "");
411	        if (ok) yield { type: "file", path, action: "write" };
412	        results.push({
413	          type: "tool_result",
414	          tool_use_id: use.id,
415	          content: ok ? `Wrote ${path}.` : `Could not write ${path}.`,
416	          is_error: !ok,
417	        });
418	      } else if (use.name === "delete_file") {
419	        const ok = await opts.onDelete(path);
420	        if (ok) yield { type: "file", path, action: "delete" };
421	        results.push({
422	          type: "tool_result",
423	          tool_use_id: use.id,
424	          content: ok ? `Deleted ${path}.` : `${path} did not exist.`,
425	          is_error: false,
426	        });
427	      } else {
428	        results.push({
429	          type: "tool_result",
430	          tool_use_id: use.id,
431	          content: `Unknown tool ${use.name}.`,
432	          is_error: true,
433	        });
434	      }
435	    }
436	
437	    messages.push({ role: "user", content: results });
438	  }
439	
440	  yield { type: "usage", model, ...totals };
